<?php require_once __DIR__.'/../includes/auth.php';requireHOD();$p=db();$id=(int)($_GET['id']??0);$q=$p->prepare('SELECT a.*,b.batch_code,s.subject_code,s.subject_name,se.semester_name,u.name lecturer FROM attendance_sessions a JOIN batch_subjects bs ON bs.id=a.batch_subject_id JOIN batches b ON b.id=bs.batch_id JOIN subjects s ON s.id=bs.subject_id JOIN semesters se ON se.id=bs.semester_id JOIN users u ON u.id=bs.lecturer_id WHERE a.id=? AND b.department_id=?');$q->execute([$id,$_SESSION['user']['department_id']]);$session=$q->fetch();if(!$session)redirect('/hod/attendance.php');$q=$p->prepare('SELECT st.registration_number,st.student_name,ar.status FROM attendance_records ar JOIN students st ON st.id=ar.student_id WHERE ar.attendance_session_id=? ORDER BY st.registration_number');$q->execute([$id]);$title='Attendance Session';require __DIR__.'/../includes/header.php';?><section class="panel"><h2><?=e($session['subject_code'].' — '.$session['subject_name'])?></h2><p>Date: <?=e($session['attendance_date'])?> | Batch: <?=e($session['batch_code'])?> | <?=e($session['semester_name'])?> | Lecturer: <?=e($session['lecturer'])?> | Lecture <?=str_pad((string)$session['lecture_number'],2,'0',STR_PAD_LEFT)?> | <?=e(ucfirst($session['session_type']))?></p><div class="table-wrap"><table><tr><th>Registration</th><th>Student</th><th>Status</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['registration_number'])?></td><td><?=e($r['student_name']?:'Name not entered')?></td><td class="status-<?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></td></tr><?php endforeach?></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
